export function distinctCartVendors(cart: Cart, catalogId: string): string[] {
  const vendors = [];
  for (const entry of cart.entries) {
    if (entry.catalogId !== catalogId) continue;
    vendors.push(entry.vendor);
  }
  return vendors;
}

